### C++

```cpp
#include <iostream>
#include <string>
#include <vector>
using namespace std;

const int MOD = 1000000007;

int solve_one(int m, const string& pat) {
    vector<long long> f(26, 0);
    // 初始化 f[c]：第一位是 '?' 则所有 c 都为 1，否则只有固定字符为 1
    if (pat[0] == '?')
        for (int c = 0; c < 26; ++c) f[c] = 1;
    else
        f[pat[0] - 'a'] = 1;

    long long total = 0;
    for (int c = 0; c < 26; ++c) total += f[c];
    total %= MOD;

    for (int i = 1; i < m; ++i) {
        vector<long long> nf(26, 0);  // 下一轮 f
        if (pat[i] == '?') {
            // 通配符：每个字符 c 不能和上一位相同
            for (int c = 0; c < 26; ++c)
                nf[c] = (total - f[c] + MOD) % MOD;
        } else {
            // 固定字符：只更新对应位置
            int c = pat[i] - 'a';
            nf[c] = (total - f[c] + MOD) % MOD;
        }
        f.swap(nf);
        total = 0;
        for (int c = 0; c < 26; ++c) total += f[c];
        total %= MOD;
        if (total == 0) break;
    }
    return (int)total;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int T; cin >> T;
    while (T--) {
        int m; string pat;
        cin >> m >> pat;       // cin 会自动跳过换行，支持两行输入
        cout << solve_one(m, pat) << '\n';
    }
    return 0;
}
